const STATE = require('STATE')
const statedb = STATE(__filename)
const { get } = statedb(fallback_module)
const net = require('net_helper')

const theme_widget = require('theme_widget')
const tab_group = require('tab_group')

module.exports = tile_manager

async function tile_manager(opts, invite) {
  const { id, sdb } = await get(opts.sid)
  const { drive } = sdb

  const on = {
    style: inject
  }

  const layout = {
    root: { type: 'leaf', tile_id: 0, el: null },
    collapse_level: 0,
    focused_tile: 0
  }
  const tile_registry = {}

  const cached_actions = {
    update_actions_for_app: null,
    update_quick_actions_for_app: null,
    update_steps_wizard_for_app: null
  }

  const tile_tabs = {}

  let tile_counter = 1
  let split_counter = 1
  const COLLAPSE_THRESHOLD = 600
  const { io, _ } = net(id)

  const el = document.createElement('div')
  const shadow = el.attachShadow({ mode: 'closed' })
  shadow.innerHTML = `<div class="tile-manager-wrapper">
    <div class="tile-manager"></div>
  </div>`
  const sheet = new CSSStyleSheet()
  shadow.adoptedStyleSheets = [sheet]
  const wrapper = shadow.querySelector('.tile-manager-wrapper')
  const container = shadow.querySelector('.tile-manager')

  const subs = await sdb.watch(onbatch)

  io.on = {
    up: io_up()
  }
  if (invite) io.accept(invite)

  const resize_observer = new ResizeObserver(on_resize_observed)
  resize_observer.observe(el)

  container.addEventListener('pointerdown', function (e) {
    const slot = e.target.closest ? e.target.closest('.tile-slot') : null
    if (!slot) return
    const tile_id = parseInt(slot.getAttribute('data-tile-id'), 10)
    if (!isNaN(tile_id) && tile_id !== layout.focused_tile) {
      set_focused_tile(tile_id)
    }
  }, true)

  function on_resize_observed(entries) {
    for (const entry of entries) {
      handle_resize(entry.contentRect.width)
    }
  }

  await render_layout_tree()

  return el

  function get_tree_depth(node) {
    if (!node) return 0
    if (node.type === 'leaf') return 0
    let max_child_depth = 0
    for (const child of node.children) {
      const d = get_tree_depth(child)
      if (d > max_child_depth) max_child_depth = d
    }
    return 1 + max_child_depth
  }

  function get_max_collapse_level() {
    return get_tree_depth(layout.root)
  }

  function collect_hierarchy(node, depth) {
    if (!node) return null
    if (node.type === 'leaf') {
      return {
        type: 'leaf',
        tile_id: node.tile_id,
        tabs: tile_tabs[node.tile_id] || [],
        children: []
      }
    }
    const result = {
      type: 'split',
      direction: node.direction,
      depth: depth,
      children: []
    }
    for (const child of node.children) {
      const child_hier = collect_hierarchy(child, depth + 1)
      if (child_hier) result.children.push(child_hier)
    }
    return result
  }

  function collect_collapsed_at_level(node, current_depth, collapse_level) {
    if (!node) return []
    if (node.type === 'leaf') {
      return [{
        type: 'leaf',
        tile_id: node.tile_id,
        tabs: tile_tabs[node.tile_id] || [],
        children: []
      }]
    }

    const target_collapse_depth = collapse_level - 1
    if (current_depth >= target_collapse_depth) {
      return [{
        type: 'collapsed_group',
        split_id: node.split_id,
        direction: node.direction,
        depth: current_depth,
        children: node.children.map(child => collect_collapsed_group(child))
      }]
    }

    const results = []
    for (const child of node.children) {
      const child_results = collect_collapsed_at_level(child, current_depth + 1, collapse_level)
      results.push(...child_results)
    }
    return results
  }

  function collect_collapsed_group(node) {
    if (!node) return null
    if (node.type === 'leaf') {
      return {
        type: 'leaf',
        tile_id: node.tile_id,
        tabs: tile_tabs[node.tile_id] || [],
        children: []
      }
    }
    return {
      type: 'split_group',
      split_id: node.split_id,
      direction: node.direction,
      children: node.children.map(child => collect_collapsed_group(child)).filter(Boolean)
    }
  }

  function has_tile_0(node) {
    if (!node) return false
    if (node.type === 'leaf') return node.tile_id === 0
    return node.children.some(child => has_tile_0(child))
  }

  function get_first_leaf(node) {
    if (!node) return null
    if (node.type === 'leaf') return node
    return get_first_leaf(node.children[0])
  }

  function handle_resize(width) {
    if (get_tiles().length < 2) {
      if (layout.collapse_level !== 0) {
        set_collapse_level(0)
      }
      return
    }

    const should_collapse = width < COLLAPSE_THRESHOLD

    if (should_collapse && layout.collapse_level === 0) {
      set_collapse_level(1)
    } else if (!should_collapse && layout.collapse_level > 0) {
      set_collapse_level(0)
    }
  }

  function set_collapse_level(level) {
    const max_level = get_max_collapse_level()
    const clamped_level = Math.max(0, Math.min(level, max_level))

    console.error('tile_manager: set_collapse_level', clamped_level, '(max:', max_level, ')')
    layout.collapse_level = clamped_level

    if (clamped_level === 0) {
      const root_tile_send = _.tile_0
      if (root_tile_send) {
        root_tile_send('hide_collapsed_tab_group', {}, {})
      }
    } else {
      const hierarchy = collect_hierarchy(layout.root, 0)
      const collapsed_groups = collect_collapsed_at_level(layout.root, 0, clamped_level)
      const root_tile_send = _.tile_0
      if (root_tile_send) {
        root_tile_send('show_collapsed_tab_group', {}, {
          nested: true,
          collapse_level: clamped_level,
          max_level: max_level,
          hierarchy: hierarchy,
          collapsed_groups: collapsed_groups
        })
      }
    }

    render_layout_tree().catch(err => {
      console.error('tile_manager: collapse level render failed', err)
    })
  }

  function get_tiles() {
    return collect_leaf_ids().map(tile_id => tile_registry[tile_id]).filter(Boolean)
  }

  function collect_leaf_ids(node = layout.root, tile_ids = []) {
    if (!node) return tile_ids
    if (node.type === 'leaf') {
      tile_ids.push(node.tile_id)
      return tile_ids
    }
    node.children.forEach(child => collect_leaf_ids(child, tile_ids))
    return tile_ids
  }

  function find_leaf_node(tile_id, node = layout.root, parent = null, index = -1) {
    if (!node) return null
    if (node.type === 'leaf') {
      return node.tile_id === tile_id ? { node, parent, index } : null
    }
    for (let child_index = 0; child_index < node.children.length; child_index++) {
      const match = find_leaf_node(tile_id, node.children[child_index], node, child_index)
      if (match) return match
    }
    return null
  }

  function replace_leaf_node(tile_id, next_node) {
    const match = find_leaf_node(tile_id)
    if (!match) return false
    if (!match.parent) {
      layout.root = next_node
      return true
    }
    match.parent.children[match.index] = next_node
    return true
  }

  async function ensure_tile(tile_id) {
    if (tile_registry[tile_id]) return tile_id

    const sub_entry = subs[tile_id] || { sid: opts.sid }
    const tile_info = {
      id: tile_id,
      element: null,
      slot: null,
      sid: sub_entry.sid
    }
    tile_registry[tile_id] = tile_info
    console.error('tile_manager: tile_info added for tile', tile_id)

    io.on[`tile_${tile_id}`] = io_tile(tile_id)
    console.error('tile_manager: handler registered for tile_' + tile_id)
    const tile_invite = io.invite(`tile_${tile_id}`, { up: id })
    console.error('tile_manager: invite created for tile_' + tile_id, '_[tile_' + tile_id + '] exists:', !!_[`tile_${tile_id}`])

    const component = tile_id === 0 ? theme_widget : tab_group
    const tile_el = await component(
      { ...sub_entry, ids: { up: id } },
      tile_invite
    )

    tile_info.element = tile_el

    console.error('tile_manager: created tile', tile_id)
    return tile_id
  }

  async function render_layout_tree() {
    const collapse_level = layout.collapse_level
    const max_level = get_max_collapse_level()

    container.classList.toggle('collapsed', collapse_level > 0)

    wrapper.setAttribute('data-collapse-level', collapse_level)
    wrapper.setAttribute('data-max-level', max_level)

    for (let c = 0; c <= 10; c++) {
      container.classList.remove('collapse-level-' + c)
    }
    if (collapse_level > 0) {
      container.classList.add('collapse-level-' + collapse_level)
    }

    let rendered_tree
    if (collapse_level === 1) {
      rendered_tree = await render_leaf_node(0)
    } else if (collapse_level > 1) {
      rendered_tree = await render_node_at_level(layout.root, 0, collapse_level)
    } else {
      rendered_tree = await render_node(layout.root)
    }

    sync_dom_children(container, rendered_tree ? [rendered_tree] : [])
    set_focused_tile(layout.focused_tile)
  }

  async function render_node(node) {
    if (!node) return null
    if (node.type === 'leaf') return render_leaf_node(node.tile_id)

    if (!node.el) node.el = document.createElement('div')
    node.el.className = `tile-split ${node.direction}`

    const child_elements = []
    for (const child of node.children) {
      const child_el = await render_node(child)
      if (child_el) child_elements.push(child_el)
    }
    sync_dom_children(node.el, child_elements)
    return node.el
  }

  async function render_node_at_level(node, depth, collapse_level) {
    if (!node) return null

    const target_collapse_depth = collapse_level - 1

    if (node.type === 'leaf') {
      return render_leaf_node(node.tile_id)
    }

    if (depth >= target_collapse_depth) {
      if (has_tile_0(node)) {
        const child_with_0 = node.children.find(child => has_tile_0(child))
        return render_node_at_level(child_with_0, depth + 1, collapse_level)
      }
      const first_leaf = get_first_leaf(node)
      return render_leaf_node(first_leaf.tile_id)
    }

    if (!node.el) node.el = document.createElement('div')
    node.el.className = `tile-split ${node.direction}`

    const child_elements = []
    for (const child of node.children) {
      const child_el = await render_node_at_level(child, depth + 1, collapse_level)
      if (child_el) child_elements.push(child_el)
    }

    if (child_elements.length === 1) {
      return child_elements[0]
    }

    sync_dom_children(node.el, child_elements)
    return node.el
  }

  async function render_leaf_node(tile_id) {
    const match = find_leaf_node(tile_id)
    const node = match?.node
    if (!node) return null
    await ensure_tile(tile_id)
    const tile_info = tile_registry[tile_id]
    if (!tile_info) return null

    if (!node.el) {
      node.el = document.createElement('div')
      node.el.className = 'tile-slot'
    }
    node.el.setAttribute('data-tile-id', tile_id)
    tile_info.slot = node.el

    if (node.el.firstChild !== tile_info.element) {
      node.el.replaceChildren(tile_info.element)
    }
    return node.el
  }

  function sync_dom_children(parent, desired_children) {
    let current_index = 0

    for (const child of desired_children) {
      const current_child = parent.childNodes[current_index]
      if (current_child !== child) {
        parent.insertBefore(child, current_child || null)
      }
      current_index++
    }

    while (parent.childNodes.length > desired_children.length) {
      parent.removeChild(parent.lastChild)
    }
  }


  function io_tile(tile_id) {
    return function tile_protocol(msg) {
      const { type, data } = msg
      console.error(`tile_manager: message from tile_${tile_id}`, type, data)

      if (tile_id === 0 && type === 'tab_group_tile_clicked') {
        console.error('tile_manager: tab group tile clicked, expanding split')
        set_collapse_level(0)
        return
      }

      if (tile_id === 0 && type === 'request_collapse_level') {
        if (data && typeof data.level === 'number') {
          set_collapse_level(data.level)
        }
        return
      }

      if (type === 'ui_focus') {
        set_focused_tile(tile_id)
      }

      if (type === 'tab_name_clicked' && tile_id !== 0) {
        if (data && data.id && tile_tabs[tile_id]) {
          const exists = tile_tabs[tile_id].find(t => t.id === data.id)
          if (!exists) {
            tile_tabs[tile_id].push({ id: data.id, name: data.name, program: data.program })
          }
        }
      }
      if (type === 'tab_close_clicked' && tile_id !== 0) {
        if (data && data.id && tile_tabs[tile_id]) {
          tile_tabs[tile_id] = tile_tabs[tile_id].filter(t => t.id !== data.id)
        }
      }

      if (tile_id !== 0 && type === 'all_tabs_closed') {
        console.error('tile_manager: all tabs closed in split tile', tile_id)
        handle_merge(tile_id)
        return
      }

      if (type === 'action_auto_completed' || type === 'action_complete') {
        console.error('tile_manager: action completed, checking for split', data)
        const action = data?.selected_action
        console.error('tile_manager: action name:', action?.name)
        if (action?.name === 'Split Tile') {
          let direction = null

          if (data.result) {
            try {
              const results = JSON.parse(data.result)
              direction = results[0]
              console.error('tile_manager: direction from result:', direction)
            } catch (e) {
              console.error('tile_manager: failed to parse result', e)
            }
          }

          if (!direction) {
            const split_step = action.steps.find(s => s.component === 'form_tile_split_choice')
            console.error('tile_manager: split_step found:', split_step)
            if (split_step && split_step.data) {
              direction = split_step.data
            }
          }

          if (direction) {
            console.error('tile_manager: split requested', direction, 'from tile', tile_id)
            handle_split(tile_id, direction)
          } else {
            console.error('tile_manager: no direction found, cannot split')
          }
        }
      }

      const refs = msg.head ? { cause: msg.head } : {}
      _.up?.(type, refs, data)
    }
  }

  async function handle_split(source_tile_id, direction) {
    const source_match = find_leaf_node(source_tile_id)
    if (!source_match) {
      console.error('tile_manager: source tile not found for split', source_tile_id)
      return
    }

    const new_tile_id = tile_counter++
    const new_leaf = { type: 'leaf', tile_id: new_tile_id, el: null }
    const source_leaf = source_match.node
    const is_horizontal = direction === 'left' || direction === 'right'
    const split_node = {
      type: 'split',
      split_id: split_counter++,
      direction: is_horizontal ? 'horizontal' : 'vertical',
      split_direction: direction,
      children: direction === 'left' || direction === 'up'
        ? [new_leaf, source_leaf]
        : [source_leaf, new_leaf],
      el: null
    }

    replace_leaf_node(source_tile_id, split_node)
    await render_layout_tree()

    send_cached_actions_to_tile(new_tile_id)

    const new_tile_send = _[`tile_${new_tile_id}`]
    if (new_tile_send) {
      const tab_data = { name: 'New Tab', program: 'text_editor' }
      new_tile_send('create_default_tab', {}, tab_data)
      if (!tile_tabs[new_tile_id]) tile_tabs[new_tile_id] = []
      tile_tabs[new_tile_id].push({ id: `tab_initial_${new_tile_id}`, name: tab_data.name, program: tab_data.program })
    }

    console.error('tile_manager: split complete', direction, get_tiles().length, 'tiles')
  }

  function handle_merge(tile_id_to_remove) {
    console.error('tile_manager: handle_merge', tile_id_to_remove)

    const match = find_leaf_node(tile_id_to_remove)
    if (!match || !match.parent) {
      console.error('tile_manager: tile not found for merge', tile_id_to_remove)
      return
    }

    const sibling_index = match.index === 0 ? 1 : 0
    const sibling_node = match.parent.children[sibling_index]

    if (match.parent === layout.root) {
      layout.root = sibling_node
    } else {
      const did_replace = replace_split_parent(layout.root, match.parent, sibling_node)
      if (!did_replace) {
        console.error('tile_manager: failed to replace merge parent for tile', tile_id_to_remove)
        return
      }
    }

    const tile_info = tile_registry[tile_id_to_remove]
    if (tile_info?.element?.parentNode) {
      tile_info.element.parentNode.remove()
    }
    delete tile_registry[tile_id_to_remove]
    delete tile_tabs[tile_id_to_remove]

    if (layout.collapse_level > 0) {
      set_collapse_level(0)
    } else {
      render_layout_tree().catch(err => console.error('tile_manager: merge render failed', err))
    }

    console.error('tile_manager: merge complete, tiles remaining:', get_tiles().length)
  }

  function replace_split_parent(node, target_parent, replacement_node) {
    if (!node || node.type === 'leaf') return false
    for (let index = 0; index < node.children.length; index++) {
      if (node.children[index] === target_parent) {
        node.children[index] = replacement_node
        return true
      }
      if (replace_split_parent(node.children[index], target_parent, replacement_node)) return true
    }
    return false
  }

  function set_focused_tile(tile_id) {
    console.error('tile_manager: set_focused_tile', tile_id)
    layout.focused_tile = tile_id

    for (const tile of get_tiles()) {
      const slot = tile.slot
      if (slot) {
        slot.classList.toggle('focused', tile.id === tile_id)
      }
    }

    for (const tile of get_tiles()) {
      const send = _[`tile_${tile.id}`]
      if (send) {
        send('tile_focus_changed', {}, { focused_tile: tile_id, is_focused: tile.id === tile_id })
      }
    }
  }

  function send_cached_actions_to_tile(tile_id) {
    const send = _[`tile_${tile_id}`]
    if (!send) {
      console.error('tile_manager: cannot send cached actions, tile_' + tile_id + ' not found')
      return
    }

    console.error('tile_manager: sending cached actions to tile_' + tile_id)

    for (const [type, data] of Object.entries(cached_actions)) {
      if (data !== null) {
        console.error('tile_manager: sending cached', type, 'to tile_' + tile_id)
        send(type, {}, data)
      }
    }
  }

  function io_up() {
    const cacheable = {
      update_actions_for_app: true,
      update_quick_actions_for_app: true,
      update_steps_wizard_for_app: true
    }
    return function onmessage(msg) {
      const { type, data } = msg
      console.error('tile_manager: message from root', type, 'tiles:', get_tiles().length)
      if (cacheable[type]) {
        cached_actions[type] = data
        console.error('tile_manager: cached', type)
      }
      const refs = msg.head ? { cause: msg.head } : {}
      for (const tile of get_tiles()) {
        const send = _[`tile_${tile.id}`]
        if (send) send(type, refs, data)
      }
    }
  }

  async function onbatch(batch) {
    for (const { type, paths } of batch) {
      const data = await Promise.all(paths.map(load_path_raw))
      const func = on[type] || fail
      func({ data, type })
    }

    function load_path_raw(path) { return drive.get(path).then(read_drive_file_raw) }
    function read_drive_file_raw(file) { return file.raw }
  }

  function inject({ data }) { sheet.replaceSync(data[0]) }

  function fail({ data, type }) { console.warn('tile_manager: invalid message', { cause: { data, type } }) }
}

function fallback_module() {
  return {
    api: fallback_instance,
    _: {
      theme_widget: {
        $: ''
      },
      tab_group: {
        $: ''
      },
      net_helper: {
        $: ''
      }
    }
  }

  function fallback_instance() {
    return {
      _: {
        theme_widget: {
          0: '',
          mapping: {
            style: 'style',
            icons: 'icons',
            commands: 'commands',
            scroll: 'scroll',
            actions: 'actions',
            hardcons: 'hardcons',
            files: 'files',
            highlight: 'highlight',
            active_tab: 'active_tab',
            entries: 'entries',
            runtime: 'runtime',
            mode: 'mode',
            flags: 'flags',
            keybinds: 'keybinds',
            undo: 'undo',
            focused: 'focused',
            temp_actions: 'temp_actions',
            temp_quick_actions: 'temp_quick_actions',
            prefs: 'prefs',
            variables: 'variables',
            data: 'data',
            docs: 'docs',
            docs_style: 'docs_style'
          }
        },
        tab_group: {
          1: '',
          2: '',
          3: '',
          mapping: {
            style: 'style',
            icons: 'icons',
            actions: 'actions',
            docs: 'docs',
            docs_style: 'docs_style'
          }
        },
        net_helper: {
          0: ''
        }
      },
      drive: {
        'style/': {
          'tile_manager.css': {
            $ref: 'style/tile_manager.css'
          }
        }
      }
    }
  }
}
